insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنْ زَيْدِ بنِ خالِدِ بْنِ زَيْدٍ الْجُهَنِيِّ رَضِيَ اللهُ عَنْهُ صاحِبِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: سُئِلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ اللُّقَطَةِ: الذَّهَبِ أَوِ الْوَرِقِ؟ فَقَالَ: "اعْرِفْ وِكَاءَهَا وَعِفَاصَهَا، ثُمَّ عَرِّفْهَا سَنَةً، فَإِنْ لَمْ تَعْرِفْ فَاسْتَنْفِقْهَا، وَلْتَكُنْ وَدِيعَةً عِنْدَكَ، فَإِنْ جَاءَ طَالِبُهَا يَوْمًا مِنَ الدَّهْرِ فَأَدِّهَا إِلَيْهِ". وَسَأَلَهُ عَنْ ضَالَّةِ الإِبِلِ؟ فَقَالَ: "مَا لَكَ وَلَهَا؟ دَعْهَا، فَإِنَّ مَعَهَا حِذَاءَهَا وَسِقَاءَهَا، تَرِدُ الْمَاءَ وَتَأْكُلُ الشَّجَرَ حَتَّى يَجِدَهَا رَبُّهَا". وَسَأَلَهُ عَنِ الشَّاةِ؟ فَقَالَ: "خُذْهَا، فَإِنَّمَا هِيَ لَكَ أَوْ لِأَخِيكَ أَوْ لِلذِّئْبِ". وَفِي رِوَايَةٍ: لَمَّا سُئِلَ عَنِ الضالَّةِ، فَغَضِبَ وَاحْمَرَّتْ وَجْنَتَاهُ. (ق)', 'റസൂൽ(സ)യുടെ സഹചാരിയായിരുന്ന സൈദുബ്നുഖാലിദിബ്നി സൈദിൽ ജുഹനീ(റ): റസൂൽ(സ) വീണുകിട്ടിയ സ്വർണ്ണത്തെക്കുറിച്ച് അല്ലെങ്കിൽ വെള്ളിയെ സംബന്ധിച്ച് ചോദിക്കപ്പെട്ടു. റസൂൽ(സ) പറഞ്ഞു: "അതിന്റെ സഞ്ചിയും അടപ്പും സൂക്ഷിച്ച് വെച്ച്, ഒരു വർഷം അത് വിളംബരം ചെയ്യുക, അത് സംബന്ധിച്ച് ഒരു വിവരവും ലഭിച്ചില്ലെങ്കിൽ നീ അത് ചെലവഴിക്കുക, അത് നിന്റെയടുക്കൽ സൂക്ഷിപ്പുസ്വത്തായിരിക്കട്ടെ. ഏതെങ്കിലും ഒരു ദിനം അതിനൊരു ഉടമസ്ഥൻ വന്നാൽ നീ അവനത് വീട്ടിക്കൊടുക്കുക." വഴിതെറ്റിപ്പോയ ഒട്ടകത്തെ സംബന്ധിച്ച് റസൂൽ(സ)യോട് ചോദിച്ചു. റസൂൽ(സ) പറഞ്ഞു: "അതിനും നിനക്കും എന്ത് ബന്ധം? അതിനെ വിട്ടേക്കുക, അതിന്റെ വെള്ളപ്പാത്രവും പാദരക്ഷയും അതോട് കൂടെത്തന്നെയുണ്ട്. അതിന്റെ ഉടമസ്ഥൻ അതിനെ എത്തിക്കുവോളം അത് ഇലകൾ ഭക്ഷിക്കുകയും വെള്ളത്തിനരികിലേക്ക് പോയി കുടിക്കുകയും ചെയ്യും." ആടിനെക്കുറിച്ച് ചോദിച്ചപ്പോൾ നബി(സ) പറഞ്ഞു: "നീ അതെടുക്കുക. അത് നിനക്കുള്ളതോ അല്ലെങ്കിൽ നിന്റെ സഹോദരനുള്ളതോ അതുമല്ലെങ്കിൽ ചെന്നായക്കുള്ളതോ ആണ്." മറ്റൊരു നിവേദനത്തിൽ: ഒട്ടകത്തെ സംബന്ധിച്ച് ചോദിച്ചപ്പോൾ നബി(സ) ദേഷ്യം പിടിക്കുകയും കവിൾത്തടങ്ങൾ ചുവക്കുകയും ചെയ്തു. (ബു,മു)', 'زَيْدِ بنِ خالِدِ بْنِ زَيْدٍ الْجُهَنِيِّ', 'റസൂൽ(സ)യുടെ സഹചാരിയായിരുന്ന സൈദുബ്നുഖാലിദിബ്നി സൈദിൽ ജുഹനീ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 623, 623, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=10 and h.hadith_no=1), 1, 'وَفِي رِوَايَةٍ: لَمَّا سُئِلَ عَنِ الضالَّةِ، فَغَضِبَ وَاحْمَرَّتْ وَجْنَتَاهُ. (ق)', 'മറ്റൊരു നിവേദനത്തിൽ: ഒട്ടകത്തെ സംബന്ധിച്ച് ചോദിച്ചപ്പോൾ നബി(സ) ദേഷ്യം പിടിക്കുകയും കവിൾത്തടങ്ങൾ ചുവക്കുകയും ചെയ്തു. (ബു,മു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنْ سُوَيْدِ بْنِ غَفَلَةَ رَضِيَ اللهُ عَنْهُ قَالَ: خَرَجْتُ مَعَ زَيْدِ بْنِ صُوحَانَ وَسَلْمَانَ بْنِ رَبِيعَةَ، فَوَجَدْتُ سَوْطًا، قَالَا: دَعْهُ. فَقُلْتُ: لَا أَدَعُهُ تَأْكُلُهُ السِّبَاعُ، لَآخُذَنَّهُ فَلَأَسْتَمْتِعَنَّ بِهِ. فَقَدِمْتُ عَلَى أُبَيِّ بْنِ كَعْبٍ فَسَأَلْتُهُ عَنْ ذَلِكَ وَحَدَّثْتُهُ الْحَدِيثَ، فَقَالَ: أَحْسَنْتَ، وَجَدْتُ عَلَى عَهْدِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صُرَّةً فِيهَا مِائَةُ دِينَارٍ، قَالَ: فَأَتَيْتُهُ بِهَا، فَقَالَ لِي: "عَرِّفْهَا حَوْلًا". فَعَرَّفْتُهَا حَوْلًا فَمَا أَجِدُ مَنْ يَعْرِفُهَا، ثُمَّ أَتَيْتُهُ بِهَا، فَقَالَ: "عَرِّفْهَا حَوْلًا آخَرَ". فَعَرَّفْتُهَا ثُمَّ أَتَيْتُهُ بِهَا، فَقَالَ: "عَرِّفْهَا حَوْلًا آخَرَ". وَقَالَ: "أَحْصِ عِدَّتَهَا وَوِعَاءَهَا وَوِكَاءَهَا، فَإِنْ جَاءَ طَالِبُهَا فَأَخْبِرْكَ بِعِدَّتِهَا وَوِعَائِهَا وَوِكَائِهَا فَادْفَعْهَا إِلَيْهِ، وَإِلَّا فَاسْتَمْتِعْ بِهَا". (ق,د,ت)', 'സുവൈദുബ്നു ഗഫല(റ): സൈദുബ്നു സ്വൂഹാൻ, സൽമാനുബ്നു റബീഅ് എന്നിവരോട് കൂടെ ഞാൻ പുറപ്പെട്ടു. വഴിയിൽ വെച്ച് എനിക്ക് ഒരു ചാട്ടവാർ കിട്ടി. അവർ പറഞ്ഞു: അത് ഉപേക്ഷിക്കുക. ഞാൻ പറഞ്ഞു: ഞാൻ ഇത് ഉപേക്ഷിക്കില്ല. കാട്ടുമൃഗങ്ങൾ അത് തിന്നും, അതിനാൽ ഞാനതെടുത്ത് ഉപയോഗിക്കും. അങ്ങനെ ഞാൻ ഉബയ്യുബ്നു കഅ്ബ്(റ)വിന്റെ അടുത്ത് ചെന്ന് സംഭവങ്ങൾ വിവരിക്കുകയും ഇതിനെക്കുറിച്ച് ചോദിക്കുകയും ചെയ്തു. ഉബയ്യുബ്നു കഅ്ബ്(റ) പറഞ്ഞു: വളരെ നല്ലതാണ് നീ ചെയ്തത്. നബി(സ)യുടെ കാലത്ത് നൂറു ദീനാറുള്ള ഒരു സഞ്ചി എനിക്ക് വീണുകിട്ടിയപ്പോൾ ഞാനതുമായി നബി(സ)യുടെ അടുക്കൽ ചെന്നു. അപ്പോൾ നബി(സ) എന്നോട് പറഞ്ഞു: "ഒരു വർഷം അത് വിളംബരം ചെയ്യുക." ഒരു വർഷം ഞാനത് വിളംബരം ചെയ്തെങ്കിലും അതിനെ സംബന്ധിച്ചറിയുന്ന ഒരാളെയും എനിക്ക് കിട്ടിയില്ല. പിന്നെ അതുമായി നബി(സ)യുടെ സന്നിധിയിൽ ചെന്നു. നബി(സ) പറഞ്ഞു: "ഒരു വർഷം കൂടി വിളംബരം ചെയ്യുക." അതിനാൽ ഞാൻ വിളംബരം ചെയ്തെങ്കിലും ആളെ കിട്ടിയില്ല. വീണ്ടും നബി(സ)യുടെ സന്നിധിയിൽ ചെന്നു. അപ്പോഴും പറഞ്ഞു: "ഒരു വർഷം കൂടി വിളംബരം ചെയ്യുക." എന്നിട്ട് പറഞ്ഞു: "അതിന്റെ എണ്ണവും പാത്രവും കെട്ടുന്ന കയറും നീ സൂക്ഷിച്ച് കൃത്യമായി വെക്കുക. അതിന്റെ ഉടസ്ഥൻ അതിന്റെ എണ്ണവും പാത്രത്തെയും കെട്ടുന്ന കയറിനെയും സംബന്ധിച്ച് പറയുകയും ചെയ്താൽ നീ അത് അവന് നൽകുക. ഇല്ലെങ്കിൽ നീയത് ഉപയോഗിക്കുക." (ബു,മു,ദ,തു)', 'سُوَيْدِ بْنِ غَفَلَةَ', 'സുവൈദുബ്നു ഗഫല(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 623, 624, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنْ عِيَاضِ بْنِ حِمَارٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ وَجَدَ لُقَطَةً فَلْيُشْهِدْ ذَا عَدْلٍ، أَوْ: ذَوَيْ عَدْلٍ، ثُمَّ لَا يُغَيِّرْهُ وَلَا يَكْتُمْ. فَإِنْ جَاءَ رَبُّهَا فَهُوَ أَحَقُّ بِهَا، وَإِلَّا فَهُوَ مَالُ اللهِ يُؤْتِيهِ مَنْ يَشَاءُ". (د,جه)', 'ഇയാളുബ്നു ഹിമാർ(റ): തിരുദൂതർ(സ) പറഞ്ഞു: "ആർക്കെങ്കിലും വീണുപോയ സാധനം ലഭിച്ചാൽ അതിൽ ഒരു നീതിമാനെ അല്ലെങ്കിൽ നീതിമാന്മാരെ സാക്ഷി നിർത്തട്ടെ. പിന്നീട് അതിനെ മാറ്റുകയോ മറച്ച് വെക്കുകയോ ചെയ്യരുത്. അതിന്റെ ഉടമസ്ഥൻ വന്നാൽ അതുകൊണ്ട് ഏറ്റവും ബന്ധപ്പെട്ടവൻ അവനാണ്. ഇനി ഉടമസ്ഥൻ വന്നില്ലെങ്കിൽ താൻ ഉദ്ദേശിക്കുന്നവർക്ക് അല്ലാഹു കൊടുക്കുന്ന സമ്പത്താണത്." (ദ,ജ)', 'عِيَاضِ بْنِ حِمَارٍ', 'ഇയാളുബ്നു ഹിമാർ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 624, 624, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ عَلِيَّ بْنَ أَبِي طَالِبٍ وَجَدَ دِينَارًا، فَأَتَى بِهِ فَاطِمَةَ، فَسَأَلَتْ عَنْهُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "هُوَ رِزْقُ اللهِ عَزَّ وَجَلَّ". فَأَكَلَ مِنْهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَكَلَ عَلِيٌّ وَفَاطِمَةُ، فَلَمَّا كَانَ بَعْدَ ذَلِكَ أَتَتْهُ امْرَأَةٌ تَنْشُدُ الدِّينَارَ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَا عَلِيُّ، أَدِّ الدِّينَارَ". (د)', 'അബൂസഇൗദിൽ ഖുദ്രീ(റ): അലിയ്യുബ്നു അബീത്വാലിബ്(റ)വിന് ഒരു ദീനാർ വീണുകിട്ടിയപ്പോൾ അതുമായി ഫാത്വിമ(റ)യുടെ അടുക്കൽ ചെന്നു. മഹതി അതേക്കുറിച്ച് റസൂൽ(സ)യോട് ചോദിച്ചു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അത് അല്ലാഹു നൽകുന്ന അന്നമാണ്." അങ്ങനെ അതിൽ നിന്ന് (ഭക്ഷണ സാധനങ്ങൾ വാങ്ങി) നബി(സ)യും അലി(റ)വും ഫാത്വിമാബീവി(റ)യും ഭക്ഷിച്ചു. പക്ഷേ, കുറച്ച് കഴിഞ്ഞപ്പോൾ ദീനാർ അന്വേഷിച്ച് ഒരു സ്ത്രീ വന്നു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അലീ, ദീനാർ വീട്ടിക്കൊടുക്കുക." (ദ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഇൗദിൽ ഖുദ്രീ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 624, 624, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنْ سَهْلِ بْنِ سَعْدٍ رَضِيَ اللهُ عَنْهُ: أَنَّ عَلِيَّ بْنَ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهُ دَخَلَ عَلَى فَاطِمَةَ رَضِيَ اللهُ عَنْهَا وَحَسَنٌ وَحُسَيْنٌ رَضِيَ اللهُ عَنْهُمَا يَبْكِيَانِ، فَقَالَ: مَا يُبْكِيهِمَا؟ قَالَتْ: الْجُوعُ، فَخَرَجَ عَلِيٌّ فَوَجَدَ دِينَارًا بِالسُّوقِ، فَجَاءَ إِلَى فَاطِمَةَ فَأَخْبَرَهَا، فَقَالَتْ: اذْهَبْ إِلَى فُلَانٍ الْيَهُودِيِّ فَخُذْ لَنَا دَقِيقًا. فَجَاءَ الْيَهُودِيُّ فَاشْتَرَى بِهِ، فَقَالَ الْيَهُودِيُّ: أَنْتَ خَتَنُ هَذَا الَّذِي يَزْعُمُ أَنَّهُ رَسُولُ اللهِ؟ قَالَ: نَعَمْ، قَالَ: فَخُذْ دِينَارَكَ وَلَكَ الدَّقِيقُ. فَخَرَجَ عَلِيٌّ حَتَّى جَاءَ بِهِ فَاطِمَةَ، فَأَخْبَرَهَا، فَقَالَتْ: اذْهَبْ إِلَى فُلَانٍ الْجَزَّارِ فَخُذْ لَنَا بِدِرْهَمٍ لَحْمًا. فَذَهَبَ فَرَهَنَ الدِّينَارَ بِدِرْهَمٍ لَحْمٍ، فَجَاءَ بِهِ، فَعَجَنَتْ، وَنَصَبَتْ، وَخَبَزَتْ، وَأَرْسَلَتْ إِلَى أَبِيهَا، فَجَاءَهُمْ، فَقَالَتْ: يَا رَسُولَ اللهِ، أَذْكُرُ لَكَ، فَإِنْ رَأَيْتَهُ لَنَا حَلَالًا أَكَلْنَاهُ وَأَكَلْتَ مَعَنَا، مِنْ شَأْنِهِ كَذَا وَكَذَا. فَقَالَ: "كُلُوا بِاسْمِ اللهِ". فَأَكَلُوا، فَبَيْنَمَا هُمْ مَكَانَهُمْ إِذَا غُلَامٌ يَنْشُدُ اللهَ وَالْإِسْلَامَ الدِّينَارَ، فَأَمَرَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَدُعِيَ لَهُ، فَسَأَلَهُ، فَقَالَ: سَقَطَ مِنِّي فِي السُّوقِ. فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَا عَلِيُّ، اذْهَبْ إِلَى الْجَزَّارِ فَقُلْ لَهُ: إِنَّ رَسُولَ اللهِ صَلَّى اللهُم عَلَيْهِ وَسَلَّمَ يَقُولُ لَكَ: أَرْسِلْ إِلَيَّ بِالدِّينَارِ، وَدِرْهَمُكَ عَلَيَّ". فَأَرْسَلَ بِهِ فَدَفَعَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِلَيْهِ. (د)', 'സഹ്ലുബ്നു സഅ്ദ്(റ): അലി(റ) ഫാത്വിമ(റ)യുടെ അടുത്തേക്ക് വന്നപ്പോൾ ഹസൻ(റ)വും ഹുസൈൻ(റ)വും കരഞ്ഞുകൊണ്ടിരിക്കുകയാണ്. അലി(റ) ചോദിച്ചു: എന്തിനാണ് അവർ കരയുന്നത്? മഹതി പറഞ്ഞു: വിശപ്പ്. അങ്ങനെ അലി(റ) പുറത്ത് പോയി. അങ്ങാടിയിൽ വെച്ചൊരു ദീനാർ കിട്ടി. മഹതിയുടെ അടുത്തേക്ക് വന്ന് വിവരം പറഞ്ഞു. മഹതി പറഞ്ഞു: അങ്ങ് ഇന്ന യഹൂദിയുടെ അടുക്കൽ പോയി വല്ല ധാന്യപ്പൊടിയും വാങ്ങി വരൂ. അങ്ങനെ അലി(റ) യഹൂദിയുടെ അടുത്ത് ചെന്ന് അതുകൊണ്ട് പൊടി വാങ്ങി. അപ്പോൾ യഹൂദി ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതനെന്ന് വാദിക്കുന്നയാളുടെ മരുമകനല്ലേ അങ്ങ്? അലി(റ) പറഞ്ഞു: അതെ. യഹൂദി പറഞ്ഞു: ദീനാർ താങ്കൾ എടുത്തുകൊള്ളുക. ധാന്യപ്പൊടിയും താങ്കൾക്കുള്ളതാണ്. അങ്ങനെ അതുമായി അലി(റ) ഫാത്വിമ(റ)യുടെ അടുത്ത് ചെന്ന് വിവരം പറഞ്ഞു. മഹതി പറഞ്ഞു: അങ്ങ് ഇന്ന അറവുകാരന്റെയടുക്കൽ ചെന്ന് ഒരു ദിർഹമിന് ഇറച്ചി വാങ്ങി വരൂ. അലി(റ) പോയി ഒരു ദിർഹം ഇറച്ചിക്ക് ആ ഒരു ദീനാർ പണയം വെച്ചു. ഇറച്ചി കൊണ്ടുവന്നു. മഹതി പൊടി കുഴച്ച് പരത്തി പത്തിരിയാക്കി. പിതാവിന് ആളെ അയച്ചു. റസൂൽ(സ) അവരുടെ അടുത്തേക്ക് വന്നു. മഹതി പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഞാനിതേക്കുറിച്ച് അങ്ങയോട് പറയുന്നു. അത് ഞങ്ങൾക്ക് അനുവദനീയമാണെന്ന് അങ്ങ് പറഞ്ഞാൽ ഞങ്ങളത് ഭക്ഷിക്കും. അങ്ങ് ഞങ്ങളോട് കൂടെ ഭക്ഷിക്കണം. ഇന്നതൊക്കെയാണ് അതിന്റെ കാര്യം. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളത് ബിസ്മി ചൊല്ലി കഴിക്കുക." അങ്ങനെ അവർ തിന്നു. അവർ അവിടെത്തന്നെ ഇരിക്കെ അതാ ഒരു കുട്ടി, അല്ലാഹുവിന്റെയും ഇസ്ലാമിന്റെയും പേര് പറഞ്ഞ് ദീനാർ അന്വേഷിക്കുന്നു. റസൂൽ(സ) അവനെ വിളിക്കാൻ കൽപിച്ചു. അവൻ വിളിക്കപ്പെട്ടു. അവനോടന്വേഷിച്ചു. ആ കുട്ടി പറഞ്ഞു: എന്റെ പക്കൽ നിന്നും അങ്ങാടിയിൽ കൊഴിഞ്ഞുപോയതാണ്. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അലീ(റ), ആ കശാപ്പുകാരന്റെ അടുത്തുചെന്ന്, ആ ദീനാർ എനിക്ക് തരിക, ദിർഹം എന്റെ ബാധ്യതയിലുണ്ട് എന്ന് റസൂൽ(സ) നിന്നോട് പറയുന്നുവെന്ന് പറയുക." അപ്പോൾ കശാപ്പുകാരൻ ആ ദീനാർ കൊടുത്തയക്കുകയും റസൂൽ(സ) അത് ആ കുട്ടിക്ക് നൽകുകയും ചെയ്തു. (ദ)', 'سَهْلِ بْنِ سَعْدٍ', 'സഹ്ലുബ്നു സഅ്ദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 624, 625, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ عُثْمَانَ التَّيْمِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ لُقَطَةِ الْحَاجِّ. قَالَ: يَعْنِي فِي لُقَطَةِ الْحَاجِّ يَتْرُكُهَا حَتَّى يَجِدَهَا صَاحِبُهَا. (م,د,ن)', 'അബ്ദുർറഹ്മാനിബ്നു ഉസ്മാനിത്തൈമീ(റ): ഹാജിക്ക് വീണുകിട്ടുന്ന സാധനത്തെ റസൂൽ(സ) നിരോധിച്ചിരിക്കുന്നു. നിവേദകൻ പറഞ്ഞു: അഥവാ, ഹാജിക്ക് വീണുകിട്ടുന്ന സാധനം അതിന്റെ ഉടമസ്ഥന് കിട്ടാൻ വേണ്ടി അവൻ ഒഴിച്ചിടണം. (മു,ദ,ന)', 'عَبْدِ الرَّحْمَنِ بْنِ عُثْمَانَ التَّيْمِيِّ', 'അബ്ദുർറഹ്മാനിബ്നു ഉസ്മാനിത്തൈമീ(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 625, 625, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنِّي لَأَنْقَلِبُ إِلَى أَهْلِي، فَأَجِدُ التَّمْرَةَ سَاقِطَةً عَلَى فِرَاشِي، فَأَرْفَعُهَا لِآكُلَهَا، ثُمَّ أَخْشَى أَنْ تَكُونَ صَدَقَةً فَأُلْقِيهَا". (ق)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഞാൻ എന്റെ വീട്ടിലേക്ക് ചെല്ലുമ്പോൾ, എന്റെ വീട്ടിൽ ചിലപ്പോഴൊക്കെ കാരക്ക വീണുകിടക്കുന്നത് കാണാറുണ്ട്. അത് തിന്നാൻ വേണ്ടി ഞാൻ എടുക്കും. പക്ഷേ, അത് സക്കാത്തിൽ പെട്ടതാണോ എന്ന് പേടിച്ച് ഞാനത് ഉപേക്ഷിക്കും." (ബു,മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 625, 626, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=3 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنْ زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ رَضِيَ اللهُ عَنْهُ عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، أَنَّهُ قَالَ: "مَنْ آوَى ضَالَّةً فَهُوَ ضَالٌّ، مَا لَمْ يُعَرِّفْهَا". (م)', 'സൈദുബ്നു ഖാലിദിൽ ജുഹനീ(റ): നബി(സ) പറഞ്ഞു: "വഴി തെറ്റിയ മൃഗത്തിന് അഭയം നൽകിയവൻ അതിനെ വിളംബരം ചെയ്യാത്ത കാലത്തോളം വഴിപിഴച്ചവനാണ്." (മു)', 'زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ', 'സൈദുബ്നു ഖാലിദിൽ ജുഹനീ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 626, 626, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنِ الْمُنْذِرِ بْنِ جَرِيرٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ مَعَ جَرِيرٍ بِالْبَوَازِيجِ، فَجَاءَ الرَّاعِي بِالْبَقَرِ، وَفِيهَا بَقَرَةٌ لَيْسَتْ مِنْهَا، فَقَالَ لَهُ جَرِيرٌ: مَا هَذِهِ؟ قَالَ: لَحِقَتْ بِالْبَقَرِ لَا نَدْرِي لِمَنْ هِيَ. فَقَالَ جَرِيرٌ: أَخْرِجُوهَا، فَقَدْ سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا يَأْوِي الضَّالَّةَ إِلَّا ضَالٌّ". (د,ن,جه)', 'മുൻദിറുബ്നു ജരീർ(റ): ഞാൻ ജരീറിനോട് കൂടെ ബവാസീജിലായിരുന്നു. ഇടയൻ കുറച്ച് പശുക്കളുമായി വന്നു. ആ കൂട്ടത്തിൽ പെടാത്ത ഒരു പശു അതിലുണ്ട്. ജരീർ അയാളോട് ചോദിച്ചു: ഇതെന്താണ്? അയാൾ പറഞ്ഞു: ഇത് ഇൗ പശുക്കളോട് ചേർന്നതാണ്, ആരുടേതാണെന്ന് എനിക്കറിയില്ല. അപ്പോൾ ജരീർ പറഞ്ഞു: അതിനെ വിട്ടേക്കുക. കാരണം, റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: "വഴി തെറ്റിയ മൃഗത്തിന് വഴി തെറ്റിയവനല്ലാതെ അഭയം നൽകില്ല." (ദ,ന,ജ)', 'الْمُنْذِرِ بْنِ جَرِيرٍ', 'മുൻദിറുബ്നു ജരീർ(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 626, 626, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنْ عَبْدِ اللهِ بْنِ الشِّخِّيرِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "ضَالَّةُ الْمُسْلِمِ حَرَقُ النَّارِ". (جه)', 'അബ്ദുല്ലാഹിബ്നുശ്ശിഖീർ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരു മുസ്ലിമിന്റെ വീണുപോയ സാധനം നരകത്തിന്റെ തീയാണ്." (ജ)', 'عَبْدِ اللهِ بْنِ الشِّخِّيرِ', 'അബ്ദുല്ലാഹിബ്നുശ്ശിഖീർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 626, 626, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "ضَالَّةُ الْإِبِلِ الْمَكْتُومَةُ غَرَامَتُهَا وَمِثْلُهَا مَعَهَا". (د)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "വഴി തെറ്റിപ്പോയി ഒളിപ്പിക്കപ്പെട്ട ഒട്ടകത്തിന്റെ പിഴ അതിനോടുകൂടെ അതിനോട് സമാനമായ ഒന്നിനെ കൂടി നൽകലാണ്." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 626, 626, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَحْلُبَنَّ أَحَدٌ مَاشِيَةَ أَحَدٍ إِلَّا بِإِذْنِهِ، أَيُحِبُّ أَحَدُكُمْ أَنْ تُؤْتَى مَشْرُبَتُهُ فَتُكْسَرَ خِزَانَتُهُ، فَيُنْتَقَلَ طَعَامُهُ، إِنَّمَا تَخْزُنُ لَهُمْ ضُرُوعُ مَوَاشِيهِمْ أَطْعِمَتَهُمْ، فَلَا يَحْلُبَنَّ أَحَدٌ مَاشِيَةَ أَحَدٍ إِلَّا بِإِذْنِهِ". (م)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "സമ്മതമില്ലാതെ ആരും ആരുടെയും മൃഗത്തെ കറക്കരുത്. നിങ്ങളാരെങ്കിലും തന്റെ മുറിയിൽ വന്ന് ഖജനാവ് പൊളിക്കപ്പെട്ട്, അതിലെ ഭക്ഷണം കൊണ്ടുപോകുന്നത് ഇഷ്ടപ്പെടുമോ? അവർക്ക് വേണ്ടി അവരുടെ കാലികൾ അവയുടെ അകിടിൽ ഭക്ഷണം ശേഖരിക്കുകയാണ്. അതുകൊണ്ടുതന്നെ സമ്മതമില്ലാതെ ആരും ആരുടെയും കാലികളെ കറക്കരുത്." (മു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 626, 626, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=3 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُ قَالَ: رَخَّصَ لَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي الْعَصَا وَالسَّوْطِ وَالْحَبْلِ وَأَشْبَاهِهِ يَلْتَقِطُهُ الرَّجُلُ يَنْتَفِعُ بِهِ (د)', 'ജാബിറുബ്നുഅബ്ദില്ല(റ): വീണുകിട്ടുന്ന വടി, ചാട്ടവാർ, കയർ തുടങ്ങി ഉപകാരപ്പെടുന്ന സാധനങ്ങളിൽ റസൂൽ(സ) ഞങ്ങൾക്ക് ഇളവ് ചെയ്തുതന്നിട്ടുണ്ട്. (ദ)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നുഅബ്ദില്ല(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 627, 627, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=3 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُ، عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُ سُئِلَ عَنِ الثَّمَرِ الْمُعَلَّقِ؟ فَقَالَ: "مَنْ أَصَابَ بِفِيهِ مِنْ ذِي حَاجَةٍ – غَيْرَ مُتَّخِذٍ خُبْنَةً – فَلَا شَيْءَ عَلَيْهِ، وَمَنْ خَرَجَ بِشَيْءٍ مِنْهُ فَعَلَيْهِ غَرَامَةُ مِثْلَيْهِ وَالْعُقُوبَةُ، وَمَنْ سَرَقَ مِنْهُ شَيْئًا بَعْدَ أَنْ يُؤْوِيَهُ الْجَرِينُ فَبَلَغَ ثَمَنَ الْمِجَنِّ فَعَلَيْهِ الْقَطْعُ، قَالَ: وَسُئِلَ عَنِ اللُّقَطَةِ، فَقَالَ: "مَا كَانَ مِنْهَا فِي طَرِيقِ الْمِيتَاءِ أَوِ الْقَرْيَةِ الْجَامِعَةِ فَعَرِّفْهَا سَنَةً، فَإِنْ جَاءَ طَالِبُهَا فَادْفَعْهَا إِلَيْهِ، وَإِنْ لَمْ يَأْتِ فَهِيَ لَكَ. وَمَا كَانَ فِي الْخَرَابِ – يَعْنِي – فَفِيهَا وَفِي الرِّكَازِ الْخُمُسُ". وَفِي رِوَايَةٍ: قَالَ فِي ضَالَّةِ الْغَنَمِ: "لَكَ أَوْ لِأَخِيكَ أَوْ لِلذِّئْبِ، خُذْهَا". وَفِي رِوَايَةٍ: قَالَ فِي ضَالَّةِ الشَّاءِ: "فَاجْمَعْهَا حَتَّى يَأْتِيَهَا بَاغِيهَا". (د,ت,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ)യോട് മരത്തിലുള്ള പഴത്തെക്കുറിച്ച് ചോദിക്കപ്പെട്ടു. റസൂൽ(സ) പറഞ്ഞു: "ആവശ്യക്കാരൻ അത് സൂക്ഷിച്ച് വെക്കാതെ ഭക്ഷിച്ചാൽ അവന് ഒരു പ്രശ്നവുമില്ല. അത് എടുത്ത് പുറത്ത് പോയവനുള്ള പിഴ, അതിന്റെ രണ്ടിരട്ടിയും ശിക്ഷയുമാണ്. ഒരുത്തന് മെതിക്കളത്തിൽ അഭയം നൽകിയതിന് ശേഷം, പരിചയുടെ വിലവരുന്ന സാധനം അതിൽ നിന്ന് മോഷ്ടിച്ചാൽ അവന്റെ കൈ വെട്ടൽ നിർബന്ധമാണ്." വീണുകിട്ടിയ സാധനത്തെക്കുറിച്ച് റസൂൽ(സ)യോട് ചോദിക്കപ്പെട്ടു. റസൂൽ(സ) പറഞ്ഞു: "അത് ജനനിബിഢമായ ഗ്രാമത്തിലോ നടപ്പാതയിലോ ആണെങ്കിൽ ഒരു വർഷം വിളംബരം ചെയ്യുക. അതന്വേഷിച്ച് ആരെങ്കിലും വന്നാൽ നീ അത് അവന് കൊടുക്കുക. ആരും വന്നില്ലെങ്കിൽ അത് നിനക്കുള്ളതാണ്. ഇനി അത് ശൂന്യമായ സ്ഥാനത്താണെങ്കിൽ, അതിലും ഖനിജങ്ങളായ സ്വർണ്ണം, വെള്ളി മുതലായവയിലും അഞ്ചിലൊന്ന് സകാത്ത് നൽകണം." മറ്റൊരു നിവേദനം: വഴി തെറ്റിവന്ന ആടിനെ സംബന്ധിച്ച് റസൂൽ(സ) പറഞ്ഞു: "അത് നിനക്കോ അല്ലെങ്കിൽ നിന്റെ സഹോദരനോ അല്ലെങ്കിൽ ചെന്നായക്കോ ഉള്ളതാണ്. അതിനാൽ നീ അതെടുക്കുക." മറ്റൊരു നിവേദനം: വഴി തെറ്റി വന്ന ആടിനെ സംബന്ധിച്ച് റസൂൽ(സ) പറഞ്ഞു: "അതിന്റെ അന്വേഷകൻ വരുന്നതുവരെ മറ്റുള്ളവയോടൊപ്പം കൂട്ടുക." (ദ,തു,ന,ജ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 627, 627, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=3 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=10 and h.hadith_no=14), 1, 'وَفِي رِوَايَةٍ: قَالَ فِي ضَالَّةِ الْغَنَمِ: "لَكَ أَوْ لِأَخِيكَ أَوْ لِلذِّئْبِ، خُذْهَا".', 'മറ്റൊരു നിവേദനം: വഴി തെറ്റിവന്ന ആടിനെ സംബന്ധിച്ച് റസൂൽ(സ) പറഞ്ഞു: "അത് നിനക്കോ അല്ലെങ്കിൽ നിന്റെ സഹോദരനോ അല്ലെങ്കിൽ ചെന്നായക്കോ ഉള്ളതാണ്. അതിനാൽ നീ അതെടുക്കുക."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=10 and h.hadith_no=14), 2, 'وَفِي رِوَايَةٍ: قَالَ فِي ضَالَّةِ الشَّاءِ: "فَاجْمَعْهَا حَتَّى يَأْتِيَهَا بَاغِيهَا". (د,ت,ن,جه)', 'മറ്റൊരു നിവേദനം: വഴി തെറ്റി വന്ന ആടിനെ സംബന്ധിച്ച് റസൂൽ(സ) പറഞ്ഞു: "അതിന്റെ അന്വേഷകൻ വരുന്നതുവരെ മറ്റുള്ളവയോടൊപ്പം കൂട്ടുക." (ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنْ ضُبَاعَةَ بِنْتِ الزُّبَيْرِ رَضِيَ اللهُ عَنْهَا، عَنِ الْمِقْدَادِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُ، أَنَّهُ خَرَجَ ذَاتَ يَوْمٍ إِلَى الْبَقِيعِ – وَهُوَ الْمَقْبَرَةُ – لِحَاجَتِهِ، وَكَانَ النَّاسُ لَا يَذْهَبُ أَحَدُهُمْ فِي حَاجَتِهِ إِلَّا فِي الْيَوْمَيْنِ وَالثَّلَاثَةِ، فَإِنَّمَا يَبْعَرُ كَمَا تَبْعَرُ الْإِبِلُ، ثُمَّ دَخَلَ خَرِبَةً، فَبَيْنَمَا هُوَ جَالِسٌ لِحَاجَتِهِ إِذْ رَأَى جُرَذًا أَخْرَجَ مِنْ جُحْرٍ دِينَارًا، ثُمَّ دَخَلَ فَأَخْرَجَ آخَرَ، حَتَّى أَخْرَجَ سَبْعَةَ عَشَرَ دِينَارًا، ثُمَّ أَخْرَجَ طَرَفَ خِرْقَةٍ حَمْرَاءَ. قَالَ الْمِقْدَادُ: فَسَلَلْتُ الْخِرْقَةَ فَوَجَدْتُ فِيهَا دِينَارًا، فَتَمَّتْ ثَمَانِيَةَ عَشَرَ دِينَارًا. فَخَرَجْتُ بِهَا حَتَّى أَتَيْتُ بِهَا رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأَخْبَرْتُهُ خَبَرَهَا، فَقُلْتُ: خُذْ صَدَقَتَهَا، يَا رَسُولَ اللهِ. قَالَ: "ارْجِعْ بِهَا، لَا صَدَقَةَ فِيهَا، بَارَكَ اللهُ لَكَ فِيهَا". ثُمَّ قَالَ: "لَعَلَّكَ أَتْبَعْتَ يَدَكَ فِي الْجُحْرِ". قُلْتُ: لَا، وَالَّذِي أَكْرَمَكَ بِالْحَقِّ. قَالَ: فَلَمْ يَفْنَ آخِرُهَا حَتَّى مَاتَ. (د,جه)', 'മിഖ്ദാദുബ്നു അംറ്(റ)വിൽ നിന്ന് ളുബാഅതു ബിൻത് സുബൈർ(റ): അദ്ദേഹം ഒരു ദിവസം പ്രാഥമികാവശ്യം നിർവ്വഹിക്കാൻ ബഖീഇ(ശ്മശാനഭൂമി)ലേക്ക് പോയി. ജനങ്ങൾ സാധാരണ രണ്ടോ മൂന്നോ ദിവസം കൂടുമ്പോഴാണ് പ്രാഥമികാവശ്യങ്ങൾ നിർവ്വഹിക്കാൻ പോകാറ്. അദ്ദേഹം വിസർജ്ജിക്കുന്നത് ഒട്ടകം വിസർജ്ജിക്കുന്നത് പോലെയാണ്. അദ്ദേഹം ഒരു വിജനസ്ഥലത്ത് കടന്ന് തന്റെ ആവശ്യത്തിന് ഇരുന്നപ്പോൾ ഒരു പെരുച്ചാഴിയെക്കണ്ടു. അത് ഒരു ദീനാർ കൊണ്ടുവന്ന് പുറത്തിട്ടു. പിന്നെ, അകത്ത് കടന്ന് വേറെ ഒന്ന് കൊണ്ടുവന്ന് പുറത്തിട്ടു. അങ്ങനെ പതിനേഴെണ്ണം പുറത്ത് കൊണ്ടുവന്നിട്ടു. പിന്നെ ചുവന്നൊരു ശീലക്കെട്ട് പുറത്തിട്ടു. മിഖ്ദാദ്(റ) പറയുകയാണ്: ഞാൻ ആ കെട്ട് അഴിച്ച് നോക്കിയപ്പോൾ അതിലൊരു ദീനാർ കണ്ടു. അങ്ങനെ പതിനെട്ട് പൂർണ്ണമായി. അങ്ങനെ അതുമായി ഞാൻ റസൂൽ(സ)യുടെ സന്നിധിയിൽ ചെന്ന് വിവരങ്ങളെല്ലാം പറഞ്ഞു. എന്നിട്ട് ഞാൻ പറഞ്ഞു: അങ്ങ് അതിന്റെ സകാത്ത് എടുക്കണം. റസൂൽ(സ) പറഞ്ഞു: "നീ അതുമായി തിരിച്ച് പോവുക. അതിൽ സകാത്തൊന്നുമില്ല. അതിൽ അല്ലാഹു നിനക്ക് ബർക്കത്ത് ചെയ്യട്ടെ." പിന്നെ റസൂൽ(സ) ചോദിച്ചു: "നീ മാളത്തിൽ കൈ ഇട്ടിട്ടുണ്ടാകുമല്ലേ?" ഞാൻ പറഞ്ഞു: അങ്ങയെ സത്യവുമായി അയച്ചവനെത്തന്നെയാണ് സത്യം, ഞാനത് ചെയ്തിട്ടില്ല. മിഖ്ദാദ്(റ) പറഞ്ഞു: അദ്ദേഹം മരിക്കുന്നത് വരെ അത് തീർന്നിട്ടില്ലായിരുന്നു. (ദ,ജ)', 'ضُبَاعَةَ بِنْتِ الزُّبَيْرِ', 'മിഖ്ദാദുബ്നു അംറ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 627, 628, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=3 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "فِي الرِّكَازِ الْخُمُسُ". (ق,د,ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിധിയായി കിട്ടിയതിലെ സകാത്ത് അഞ്ചിലൊന്നാണ്." (ബു,മു,ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 628, 628, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=3 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "كَانَ فِيمَنْ كَانَ قَبْلَكُمْ رَجُلٌ اشْتَرَى عَقَارًا، فَوَجَدَ فِيهَا جَرَّةً مِنْ ذَهَبٍ، فَقَالَ: اشْتَرَيْتُ مِنْكَ الْأَرْضَ، وَلَمْ أَشْتَرِ مِنْكَ الذَّهَبَ. فَقَالَ الرَّجُلُ: إِنَّمَا بِعْتُكَ الْأَرْضَ بِمَا فِيهَا. فَتَحَاكَمَا إِلَى رَجُلٍ، فَقَالَ: أَلَكُمَا وَلَدٌ؟ فَقَالَ أَحَدُهُمَا: لِي غُلَامٌ. وَقَالَ الْآخَرُ: لِي جَارِيَةٌ. قَالَ: فَأَنْكِحَا الْغُلَامَ الْجَارِيَةَ، وَلْيُنْفِقَا عَلَى أَنْفُسِهِمَا مِنْهُ، وَلْيَتَصَدَّقَا". (ق,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾക്ക് മുമ്പുണ്ടായിരുന്ന ഒരാൾ ഒരു പറമ്പ് വാങ്ങി. അതിൽ നിന്നും അയാൾക്ക് സ്വർണ്ണനിർമ്മിതമായ ഒരു ഭരണി കിട്ടിയപ്പോൾ അയാൾ പറഞ്ഞു: ഞാൻ നിന്നിൽ നിന്നും ഭൂമിയാണ് വാങ്ങിയത്. സ്വർണ്ണം വാങ്ങിയിട്ടില്ല. അപ്പോൾ മറ്റെയാൾ പറഞ്ഞു: ഞാൻ നിനക്ക് ഭൂമി വിറ്റത് അതിലെന്തുണ്ടോ അതോടു കൂടെയാണ്. അങ്ങനെ അതിന്റെ വിധിയറിയാൻ അവർ ഒരാളുടെ അടുക്കൽ പോയി. അയാൾ ചോദിച്ചു: നിങ്ങൾക്ക് രണ്ട് പേർക്കും സന്താനമുണ്ടോ? ഒരാൾ പറഞ്ഞു: എനിക്ക് ഒരാൺകുട്ടിയുണ്ട്. മറ്റെയാൾ പറഞ്ഞു: എനിക്ക് ഒരു പെൺകുട്ടിയുണ്ട്. അയാൾ പറഞ്ഞു: ഇൗ പെൺകുട്ടിയെ ആൺകുട്ടിയെക്കൊണ്ട് വിവാഹം കഴിപ്പിക്കുക. അവർ രണ്ട് പേരും അവർക്ക് വേണ്ടത് ഇൗ മുതലിൽ നിന്നും ചെലവഴിക്കട്ടെ. അവർ സ്വദഖ ചെയ്യുകയും ചെയ്യട്ടെ." (ബു,മു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 628, 628, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=3 and b.book_no=10 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
